    elif 45 <= patient.age <= 65:
        score += 2
    else:  # age > 65
        score += 3

    # Symptoms
    if 'life-limiting_condition' in patient.symptoms:
        score += 3
    elif 'chronic_pain' in patient.symptoms or 'difficulty_breathing' in patient.symptoms:
        score += 2
    elif 'fatigue' in patient.symptoms and 'pain' in patient.symptoms:
        score += 4
    else:
        score += 1

    # Duration of condition
    if patient.duration_of_condition < 3:
        score += 0
    elif 3 <= patient.duration_of_condition <= 6:
        score += 1
    elif 7 <= patient.duration_of_condition <= 12:
        score += 2
    else:  # >12 months
        score += 3

    # Comorbidities
    if patient.comorbidities >= 6:
        score += 2
    elif patient.comorbidities >= 3:
        score += 1
    else:  # 0-2 comorbidities
